import java.util.StringTokenizer

fun main() {
    val br = System.`in`.bufferedReader()
    br.readLine()
    val arr = StringTokenizer(br.readLine()).run {
        mutableListOf<String>().apply {
            while (hasMoreTokens()) add(nextToken())
        }
    }

    var cnt1 = arr.count { it == "1" }
    var ans = 0
    var cnt0 = 0

    for (x in arr) {
        if (x == "1") {
            ans = maxOf(ans, cnt0 + cnt1)
            cnt1 -= 1
        } else {
            cnt0 += 1
        }
    }

    println(maxOf(ans, cnt0 + cnt1))
}

