import java.util.StringTokenizer

fun main() {
    readLine()
    val arr = StringTokenizer(readLine())
    val list = mutableListOf<Char>()
    while (arr.hasMoreTokens()) {
        list.add(arr.nextToken()[0])
    }

    var cnt1 = list.count { it == '1' }
    var ans = 0
    var cnt0 = 0

    for (x in list) {
        if (x == '1') {
            ans = maxOf(ans, cnt0 + cnt1)
            cnt1 -= 1
        } else {
            cnt0 += 1
        }
    }

    println(maxOf(ans, cnt0 + cnt1))
}

